# Profile single process
sudo ncu --section MemoryWorkloadAnalysis --section SpeedOfLight_RooflineChart --metrics dram__bytes_read.sum,dram__sectors_read.sum,dram__bytes_write.sum,dram__sectors_write.sum,smsp__sass_thread_inst_executed_op_dadd_pred_on.sum,smsp__sass_thread_inst_executed_op_dmul_pred_on.sum,smsp__sass_thread_inst_executed_op_dfma_pred_on.sum,smsp__sass_thread_inst_executed_op_fadd_pred_on.sum,smsp__sass_thread_inst_executed_op_fmul_pred_on.sum,smsp__sass_thread_inst_executed_op_ffma_pred_on.sum --profile-from-start 0 --rule SOLFPRoofline -o profiling0 ./alps_wind_wave --restart-from=0

# Profile with MPI on one node, use application replay mode
# Only profile 1 device because the replay mode does not play well with multiple devices
sudo ncu --section MemoryWorkloadAnalysis --section SpeedOfLight_RooflineChart --metrics dram__bytes_read.sum,dram__sectors_read.sum,dram__bytes_write.sum,dram__sectors_write.sum,smsp__sass_thread_inst_executed_op_dadd_pred_on.sum,smsp__sass_thread_inst_executed_op_dmul_pred_on.sum,smsp__sass_thread_inst_executed_op_dfma_pred_on.sum,smsp__sass_thread_inst_executed_op_fadd_pred_on.sum,smsp__sass_thread_inst_executed_op_fmul_pred_on.sum,smsp__sass_thread_inst_executed_op_ffma_pred_on.sum --profile-from-start 0 --replay-mode application --devices 1 --rule SOLFPRoofline --target-processes all -o profiling0 mpirun -n 4 --map-by ppr:2:numa:PE=16 --report-bindings --allow-run-as-root --mca orte_abort_on_non_zero_status 0 --mca opal_cuda_support 1 -x OMP_NUM_THREADS=16 -x OMP_PROC_BIND=close -x OMP_PLACES=cores ./alps_wind_wave --restart-from=0